14	`include "VX_define.vh"
15	
16	module VX_ipdom_stack import VX_gpu_pkg::*; #(
17	    parameter WIDTH = 1,
18	    parameter DEPTH = 1,
19	    parameter ADDRW = `LOG2UP(DEPTH)
20	) (
21	    input  wire             clk,
22	    input  wire             reset,
23	    input wire [NW_WIDTH-1:0] wid,
24	    input  wire [WIDTH-1:0] d_val,
25	    input  wire [ADDRW-1:0] rd_ptr,
26	    input  wire             push,
27	    input  wire             pop,
28	    output wire [WIDTH-1:0] q_val,
29	    output wire             q_idx,
30	    output wire [`VX_CFG_NUM_WARPS-1:0][ADDRW-1:0] wr_ptr,
31	    output wire             empty,
32	    output wire             full
33	);
34	    localparam BRAM_DATAW = 1 + WIDTH;
35	    localparam BRAM_SIZE  = DEPTH * `VX_CFG_NUM_WARPS;
36	    localparam BRAW_ADDRW = `LOG2UP(BRAM_SIZE);
37	
38	    wire [`VX_CFG_NUM_WARPS-1:0][ADDRW-1:0] wr_ptr_w;
39	    wire [`VX_CFG_NUM_WARPS-1:0] empty_w, full_w;
40	
41	    for (genvar i = 0; i < `VX_CFG_NUM_WARPS; i++) begin : g_addressing
42	
43	        reg [ADDRW-1:0] wr_ptr_r;
44	        reg empty_r, full_r;
45	
46	        wire push_s = push && (wid == i);
47	        wire pop_s = pop && (wid == i);
48	
49	        `RUNTIME_ASSERT(~(push_s && full_r), ("runtime error: writing to a full stack!"));
50	        `RUNTIME_ASSERT(~(pop_s && empty_r), ("runtime error: reading an empty stack!"));
51	        `RUNTIME_ASSERT(~(push_s && pop_s),  ("runtime error: push and pop in same cycle not supported!"));
52	
53	        always @(posedge clk) begin
54	            if (reset) begin
55	                wr_ptr_r <= '0;
56	                empty_r  <= 1;
57	                full_r   <= 0;
58	            end else begin
59	                if (push_s) begin
60	                    wr_ptr_r <= wr_ptr_r + ADDRW'(1);
61	                    empty_r  <= 0;
62	                    full_r   <= (ADDRW'(DEPTH-1) == wr_ptr_r);
63	                end else if (pop_s) begin
64	                    wr_ptr_r <= wr_ptr_r - ADDRW'(q_idx);
65	                    empty_r  <= (rd_ptr == 0) && q_idx;
66	                    full_r   <= 0;
67	                end
68	            end
69	        end
70	
71	        assign wr_ptr_w[i] = wr_ptr_r;
72	        assign empty_w[i]  = empty_r;
73	        assign full_w[i]   = full_r;
74	    end
75	
76	    wire [BRAW_ADDRW-1:0] raddr, waddr;
77	
78	    if (DEPTH > 1 && `VX_CFG_NUM_WARPS > 1) begin : g_DW
79	        assign waddr = push ? {wr_ptr_w[wid], wid} : {rd_ptr, wid};
80	        assign raddr = {rd_ptr, wid};
81	    end else if (DEPTH > 1) begin : g_D
82	        `UNUSED_VAR (wid)
83	        assign waddr = push ? wr_ptr_w : rd_ptr;
84	        assign raddr = rd_ptr;
85	    end else if (`VX_CFG_NUM_WARPS > 1) begin : g_W
86	        `UNUSED_VAR (rd_ptr)
87	        `UNUSED_VAR (wr_ptr_w)
88	        assign waddr = wid;
89	        assign raddr = wid;
90	    end else begin : g_none
91	        `UNUSED_VAR (rd_ptr)
92	        `UNUSED_VAR (wr_ptr_w)
93	        `UNUSED_VAR (wid)
94	        assign waddr = 0;
95	        assign raddr = 0;
96	    end
97	
98	    VX_dp_ram #(
99	        .DATAW    (BRAM_DATAW),
100	        .SIZE     (BRAM_SIZE),
101	        .RDW_MODE ("R"),
102	        .RADDR_REG(1)
103	    ) ipdom_store (
104	        .clk   (clk),
105	        .reset (reset),
106	        .read  (pop),
107	        .write (push || pop),
108	        .wren  (1'b1),
109	        .waddr (waddr),
110	        .raddr (raddr),
111	        .wdata (push ? {1'b0, d_val} : {1'b1, q_val}),
112	        .rdata ({q_idx, q_val})
113	    );
114	
115	    assign wr_ptr = wr_ptr_w;
116	    assign empty  = empty_w[wid];
117	    assign full   = full_w[wid];
118	
119	endmodule
120

