14	`include "VX_define.vh"
15	
16	module VX_scheduler import VX_gpu_pkg::*; #(
17	    parameter `STRING INSTANCE_ID = "",
18	    parameter CORE_ID = 0
19	) (
20	    input wire              clk,
21	    input wire              reset,
22	
23	`ifdef PERF_ENABLE
24	    output sched_perf_t     sched_perf,
25	`endif
26	
27	    // inputs
28	    VX_warp_ctl_if.slave    warp_ctl_if,
29	`ifdef VX_CFG_EXT_RTU_ENABLE
30	    VX_async_trap_if.slave  async_trap_if,   // RTU shader-callback yield
31	`endif
32	    VX_branch_ctl_if.slave  branch_ctl_if [`VX_CFG_NUM_ALU_BLOCKS],
33	    VX_decode_sched_if.slave decode_sched_if,
34	    VX_issue_sched_if.slave issue_sched_if [`VX_CFG_ISSUE_WIDTH],
35	    VX_commit_sched_if.slave commit_sched_if,
36	
37	    // KMU bus
38	    VX_kmu_bus_if.slave     kmu_bus_if,
39	
40	    // outputs
41	    VX_schedule_if.master   schedule_if,
42	    VX_sched_csr_if.master  sched_csr_if,
43	    VX_gbar_bus_if.master   gbar_bus_if,
44	
45	    // status
46	    output wire             busy
47	);
48	    `UNUSED_SPARAM (INSTANCE_ID)
49	    `UNUSED_PARAM (CORE_ID)
50	
51	    reg [`VX_CFG_NUM_WARPS-1:0] active_warps, active_warps_n; // updated when a warp is activated or disabled
52	    reg [`VX_CFG_NUM_WARPS-1:0] stalled_warps, stalled_warps_n; // set when branch/gpgpu instructions are issued
53	
54	    reg [`VX_CFG_NUM_WARPS-1:0][`VX_CFG_NUM_THREADS-1:0] thread_masks, thread_masks_n;
55	    reg [`VX_CFG_NUM_WARPS-1:0][PC_BITS-1:0] warp_pcs, warp_pcs_n;
56	    reg [`VX_CFG_NUM_WARPS-1:0][`VX_CFG_MEM_ADDR_WIDTH-1:0] mscratch_r;
57	
58	    // Per-warp machine-mode trap CSRs. csrw writes arrive on
59	    // sched_csr_if.trap_csr_wr_*; ECALL/EBREAK hardware-write mepc/mcause/
60	    // mtval; MRET restores the warp PC from mepc.
61	    reg [`VX_CFG_NUM_WARPS-1:0][`VX_CFG_XLEN-1:0] mstatus_r, mtvec_r, mepc_r, mcause_r, mtval_r;
62	    // Pre-trap tmask saved at trap entry; restored by MRET. Lets an async RTU
63	    // callback trap narrow the warp to the yielding lanes and recover the full
64	    // mask on return. For a synchronous (ECALL) trap this is the identity save.
65	    reg [`VX_CFG_NUM_WARPS-1:0][`VX_CFG_NUM_THREADS-1:0] mscratch_tmask_r;
66	
67	    wire [NW_WIDTH-1:0]     schedule_wid;
68	    wire [`VX_CFG_NUM_THREADS-1:0] schedule_tmask;
69	    wire [PC_BITS-1:0]      schedule_pc;
70	    wire                    schedule_valid;
71	    wire                    schedule_ready;
72	
73	    // CTA dispatcher
74	    wire cta_fire;
75	    wire [NW_WIDTH-1:0] cta_wid;
76	    wire [PC_BITS-1:0] cta_PC;
77	    wire [`VX_CFG_NUM_THREADS-1:0] cta_tmask;
78	    wire [`VX_CFG_MEM_ADDR_WIDTH-1:0] cta_param;
79	    wire cta_dispatcher_busy;
80	    wire cta_init;
81	
82	    // CTA-CSR read-back from the dispatcher (it owns the per-CTA/per-warp tables).
83	    cta_csrs_t                                              cta_rd_csrs;
84	    wire [`VX_CFG_NUM_THREADS-1:0][2:0][CTA_TID_WIDTH-1:0]  cta_rd_tid;
85	    wire [NCTA_WIDTH-1:0]                                   schedule_cta_id;
86	
87	    // Warp retirement: TMC with tmask==0 permanently deactivates the warp
88	    wire cta_warp_done = warp_ctl_if.tmc_valid && (warp_ctl_if.tmc.tmask == 0);
89	
90	    VX_cta_dispatch #(
91	        .INSTANCE_ID (`SFORMATF(("%s-cta_dispatch", INSTANCE_ID)))
92	    ) cta_dispatcher (
93	        .clk        (clk),
94	        .reset      (reset),
95	        .kmu_bus_if (kmu_bus_if),
96	        .active_warps(active_warps),
97	        .warp_done  (cta_warp_done),
98	        .warp_done_wid(warp_ctl_if.wid),
99	        .cta_fire   (cta_fire),
100	        .cta_wid    (cta_wid),
101	        .cta_PC     (cta_PC),
102	        .cta_tmask  (cta_tmask),
103	        .cta_param  (cta_param),
104	        .cta_init   (cta_init),
105	        .csr_rd_wid (sched_csr_if.csr_rd_wid),
106	        .csr_rd_cta_id(sched_csr_if.csr_rd_cta_id),
107	        .cta_rd_csrs(cta_rd_csrs),
108	        .cta_rd_tid (cta_rd_tid),
109	        .schedule_wid(schedule_wid),
110	        .schedule_cta_id(schedule_cta_id),
111	        .busy       (cta_dispatcher_busy)
112	    );
113	
114	    assign sched_csr_if.cta_csrs = cta_rd_csrs;
115	    assign sched_csr_if.cta_tid  = cta_rd_tid;
116	
117	    assign sched_csr_if.mscratch  = mscratch_r[sched_csr_if.csr_rd_wid];
118	    assign sched_csr_if.csr_mstatus = mstatus_r[sched_csr_if.csr_rd_wid];
119	    assign sched_csr_if.csr_mtvec   = mtvec_r  [sched_csr_if.csr_rd_wid];
120	    assign sched_csr_if.csr_mepc    = mepc_r   [sched_csr_if.csr_rd_wid];
121	    assign sched_csr_if.csr_mcause  = mcause_r [sched_csr_if.csr_rd_wid];
122	    assign sched_csr_if.csr_mtval   = mtval_r  [sched_csr_if.csr_rd_wid];
123	
124	    // split/join
125	    wire                    join_valid;
126	    wire                    join_is_dvg;
127	    wire                    join_is_else;
128	    wire [NW_WIDTH-1:0]     join_wid;
129	    wire [`VX_CFG_NUM_THREADS-1:0] join_tmask;
130	    wire [PC_BITS-1:0]      join_pc;
131	
132	    reg [PERF_CTR_BITS-1:0] cycles;
133	
134	    wire schedule_fire = schedule_valid && schedule_ready;
135	    wire schedule_if_fire = schedule_if.valid && schedule_if.ready;
136	`ifdef VX_CFG_EXT_C_ENABLE
137	    // PC advance is driven by decompress_finished under EXT_C;
138	    `UNUSED_VAR (schedule_if_fire)
139	`endif
140	
141	    // branch
142	    wire [`VX_CFG_NUM_ALU_BLOCKS-1:0]               branch_valid;
143	    wire [`VX_CFG_NUM_ALU_BLOCKS-1:0][NW_WIDTH-1:0] branch_wid;
144	    wire [`VX_CFG_NUM_ALU_BLOCKS-1:0]               branch_taken;
145	    wire [`VX_CFG_NUM_ALU_BLOCKS-1:0][PC_BITS-1:0]  branch_dest;
146	    wire [`VX_CFG_NUM_ALU_BLOCKS-1:0]               branch_is_trap;
147	    wire [`VX_CFG_NUM_ALU_BLOCKS-1:0]               branch_is_mret;
148	    wire [`VX_CFG_NUM_ALU_BLOCKS-1:0][3:0]          branch_trap_cause;
149	    for (genvar i = 0; i < `VX_CFG_NUM_ALU_BLOCKS; ++i) begin : g_branch_init
150	        assign branch_valid[i]      = branch_ctl_if[i].valid;
151	        assign branch_wid[i]        = branch_ctl_if[i].wid;
152	        assign branch_taken[i]      = branch_ctl_if[i].taken;
153	        assign branch_dest[i]       = branch_ctl_if[i].dest;
154	        assign branch_is_trap[i]    = branch_ctl_if[i].is_trap;
155	        assign branch_is_mret[i]    = branch_ctl_if[i].is_mret;
156	        assign branch_trap_cause[i] = branch_ctl_if[i].trap_cause;
157	    end
158	
159	    // barriers
160	    wire [`VX_CFG_NUM_WARPS-1:0] bar_unlock_mask;
161	    wire bar_unlock_valid;
162	
163	    // wspawn
164	    wspawn_t wspawn;
165	    reg wspawn_valid;
166	    reg [NW_WIDTH-1:0] wspawn_wid;
167	    reg is_single_warp;
168	
169	    wire [`CLOG2(`VX_CFG_NUM_WARPS+1)-1:0] active_warps_cnt;
170	    `POP_COUNT(active_warps_cnt, active_warps);
171	
172	     always @(*) begin
173	        active_warps_n  = active_warps;
174	        stalled_warps_n = stalled_warps;
175	        thread_masks_n  = thread_masks;
176	        warp_pcs_n      = warp_pcs;
177	
178	        // dispatch warps
179	        if (cta_fire) begin
180	            active_warps_n[cta_wid] = 1;
181	            // Reusing a warp for the next CTA skips the one-time prologue and rewinds to the
182	            // kernel's per-CTA dispatch window: a fixed 20-byte (5-instruction) sequence that
183	            // reloads the entry pointer and kargs before re-calling.
184	            warp_pcs_n[cta_wid] = cta_init ? cta_PC : (warp_pcs[cta_wid] - from_fullPC(`VX_CFG_XLEN'(20)));
185	            thread_masks_n[cta_wid] = cta_tmask;
186	        end
187	
188	        // decode unlock
189	        if (decode_sched_if.valid && decode_sched_if.unlock) begin
190	            stalled_warps_n[decode_sched_if.wid] = 0;
191	        end
192	
193	        // wspawn handling
194	        if (wspawn_valid && is_single_warp) begin
195	            active_warps_n |= wspawn.wmask;
196	            for (integer i = 0; i < `VX_CFG_NUM_WARPS; ++i) begin
197	                if (wspawn.wmask[i] && (NW_WIDTH'(i) != wspawn_wid)) begin
198	                    thread_masks_n[i][0] = 1;
199	                    warp_pcs_n[i] = wspawn.pc;
200	                end
201	            end
202	            stalled_warps_n[wspawn_wid] = 0; // unlock warp
203	        end
204	
205	        // TMC handling
206	        if (warp_ctl_if.tmc_valid) begin
207	            active_warps_n[warp_ctl_if.wid]  = (warp_ctl_if.tmc.tmask != 0);
208	            thread_masks_n[warp_ctl_if.wid]  = warp_ctl_if.tmc.tmask;
209	            stalled_warps_n[warp_ctl_if.wid] = 0; // unlock warp
210	        end
211	
212	        // split handling
213	        if (warp_ctl_if.split_valid) begin
214	            if (warp_ctl_if.split.is_dvg) begin
215	                thread_masks_n[warp_ctl_if.wid] = warp_ctl_if.split.then_tmask;
216	            end
217	            stalled_warps_n[warp_ctl_if.wid] = 0; // unlock warp
218	        end
219	
220	        // join handling
221	        if (join_valid) begin
222	            if (join_is_dvg) begin
223	                if (join_is_else) begin
224	                    warp_pcs_n[join_wid] = join_pc;
225	                end
226	                thread_masks_n[join_wid] = join_tmask;
227	            end
228	            stalled_warps_n[join_wid] = 0; // unlock warp
229	        end
230	
231	        // barrier unlock handling
232	        if (bar_unlock_valid) begin
233	            stalled_warps_n &= ~bar_unlock_mask;
234	        end
235	
236	        // wsync unlock: warp pipeline drained
237	        if (warp_ctl_if.wsync_valid) begin
238	            stalled_warps_n[warp_ctl_if.wid] = 0;
239	        end
240	
241	        // Branch handling
242	        for (integer i = 0; i < `VX_CFG_NUM_ALU_BLOCKS; ++i) begin
243	            if (branch_valid[i]) begin
244	                if (branch_is_trap[i]) begin
245	                    // ECALL/EBREAK: redirect to trap vector (mtvec[1:0] = MODE field; mask off to get base address).
246	                    warp_pcs_n[branch_wid[i]] = from_fullPC(mtvec_r[branch_wid[i]] & ~`VX_CFG_XLEN'(3));
247	                end else if (branch_is_mret[i]) begin
248	                    // MRET/SRET/URET: restore the saved PC from mepc and the
249	                    // pre-trap tmask from mscratch_tmask (async-callback narrow).
250	                    // A trap is always taken by at least one active thread, so
251	                    // mscratch_tmask is non-zero after any trap; it is zero only
252	                    // in the pre-trap startup state. A bare MRET used purely as a
253	                    // privilege switch (e.g. the riscv-tests startup entering the
254	                    // test via mepc) must keep the running mask, not clear it.
255	                    warp_pcs_n[branch_wid[i]] = from_fullPC(mepc_r[branch_wid[i]]);
256	                    if (mscratch_tmask_r[branch_wid[i]] != 0) begin
257	                        thread_masks_n[branch_wid[i]] = mscratch_tmask_r[branch_wid[i]];
258	                    end
259	                end else if (branch_taken[i]) begin
260	                    warp_pcs_n[branch_wid[i]] = branch_dest[i];
261	                end
262	                stalled_warps_n[branch_wid[i]] = 0; // unlock warp
263	            end
264	        end
265	
266	        // stall the warp until decode stage
267	        if (schedule_fire) begin
268	            stalled_warps_n[schedule_wid] = 1;
269	        end
270	
271	        // advance PC.
272	    `ifdef VX_CFG_EXT_C_ENABLE
273	        // With RVC, the decompressor may emit a 2-byte instruction.
274	        if (decode_sched_if.valid) begin
275	            warp_pcs_n[decode_sched_if.wid] =
276	                warp_pcs_n[decode_sched_if.wid]
277	                + from_fullPC(decode_sched_if.is_rvc ? `VX_CFG_XLEN'(2) : `VX_CFG_XLEN'(4));
278	        end
279	    `else
280	        if (schedule_if_fire) begin
281	            warp_pcs_n[schedule_if.data.wid] = schedule_if.data.PC + from_fullPC(`VX_CFG_XLEN'(4));
282	        end
283	    `endif
284	
285	    `ifdef VX_CFG_EXT_RTU_ENABLE
286	        // A wstall'd TRACE2 retires: resume the warp (opaque path continues at
287	        // the WAIT2 PC; the callback path is additionally redirected below).
288	        if (async_trap_if.unlock) begin
289	            stalled_warps_n[async_trap_if.wid] = 1'b0;
290	        end
291	        // Async RTU shader-callback trap. Redirect the warp to mtvec, narrow
292	        // its tmask to the yielding lanes, and resume it (it was suspended on
293	        // the parked trace macro-op the trap takes over). Highest priority so
294	        // it overrides this cycle's normal advance; mepc is snapshotted from
295	        // the (frozen) warp PC in the sequential block.
296	        if (async_trap_if.valid) begin
297	            warp_pcs_n[async_trap_if.wid]      = from_fullPC(mtvec_r[async_trap_if.wid] & ~`VX_CFG_XLEN'(3));
298	            thread_masks_n[async_trap_if.wid]  = async_trap_if.tmask;
299	            stalled_warps_n[async_trap_if.wid] = 1'b0;
300	        end
301	    `endif
302	    end
303	
304	    always @(posedge clk) begin
305	        if (reset) begin
306	            stalled_warps   <= '0;
307	            warp_pcs        <= '0;
308	            active_warps    <= '0;
309	            thread_masks    <= '0;
310	            cycles          <= '0;
311	            wspawn_valid    <=  0;
312	            warp_pcs        <= '0;
313	            active_warps    <= '0;
314	            thread_masks    <= '0;
315	            is_single_warp  <= 0;
316	            mscratch_r      <= '0;
317	            mstatus_r       <= '0;
318	            mtvec_r         <= '0;
319	            mepc_r          <= '0;
320	            mcause_r        <= '0;
321	            mtval_r         <= '0;
322	            mscratch_tmask_r <= '0;
323	        end else begin
324	            active_warps   <= active_warps_n;
325	            stalled_warps  <= stalled_warps_n;
326	            thread_masks   <= thread_masks_n;
327	            warp_pcs       <= warp_pcs_n;
328	            is_single_warp <= (active_warps_cnt == $bits(active_warps_cnt)'(1));
329	
330	            // wspawn handling
331	            if (warp_ctl_if.wspawn_valid) begin
332	                wspawn_valid <= 1;
333	                wspawn.wmask <= warp_ctl_if.wspawn.wmask;
334	                wspawn.pc    <= warp_ctl_if.wspawn.pc;
335	                wspawn_wid   <= warp_ctl_if.wid;
336	            end
337	            if (wspawn_valid && is_single_warp) begin
338	                wspawn_valid <= 0;
339	                // copy mscratch from spawning warp to all newly spawned warps
340	                for (integer i = 0; i < `VX_CFG_NUM_WARPS; ++i) begin
341	                    if (wspawn.wmask[i] && (NW_WIDTH'(i) != wspawn_wid)) begin
342	                        mscratch_r[i] <= mscratch_r[wspawn_wid];
343	                    end
344	                end
345	            end
346	
347	            // CTA dispatch: latch this warp's mscratch (param). The per-CTA /
348	            // per-warp tables and the wid->cta_id map live in VX_cta_dispatch.
349	            if (cta_fire) begin
350	                mscratch_r[cta_wid] <= cta_param;
351	            end
352	
353	            // MSCRATCH write-back from CSR unit (CSR instruction)
354	            if (sched_csr_if.csr_wr_valid) begin
355	                mscratch_r[sched_csr_if.csr_wr_wid] <= sched_csr_if.csr_wr_data;
356	            end
357	
358	            // Trap CSR write-back from CSR unit (csrw mstatus/mtvec/mepc/...)
359	            if (sched_csr_if.trap_csr_wr_valid) begin
360	                case (sched_csr_if.trap_csr_wr_addr)
361	                    `VX_CSR_MSTATUS: mstatus_r[sched_csr_if.csr_wr_wid] <= sched_csr_if.trap_csr_wr_data;
362	                    `VX_CSR_MTVEC:   mtvec_r  [sched_csr_if.csr_wr_wid] <= sched_csr_if.trap_csr_wr_data;
363	                    `VX_CSR_MEPC:    mepc_r   [sched_csr_if.csr_wr_wid] <= sched_csr_if.trap_csr_wr_data;
364	                    `VX_CSR_MCAUSE:  mcause_r [sched_csr_if.csr_wr_wid] <= sched_csr_if.trap_csr_wr_data;
365	                    `VX_CSR_MTVAL:   mtval_r  [sched_csr_if.csr_wr_wid] <= sched_csr_if.trap_csr_wr_data;
366	                    default:;
367	                endcase
368	            end
369	
370	            // Hardware trap entry (ECALL/EBREAK): snapshot the faulting PC
371	            // into mepc and the cause into mcause. Ordered after the
372	            // software write so a hardware trap wins a same-cycle conflict.
373	            for (integer i = 0; i < `VX_CFG_NUM_ALU_BLOCKS; ++i) begin
374	                if (branch_valid[i] && branch_is_trap[i]) begin
375	                    mepc_r  [branch_wid[i]] <= to_fullPC(branch_dest[i]);
376	                    mcause_r[branch_wid[i]] <= `VX_CFG_XLEN'(branch_trap_cause[i]);
377	                    mtval_r [branch_wid[i]] <= '0;
378	                    // Identity save so the shared MRET tmask-restore is a no-op
379	                    // for a synchronous (ECALL/EBREAK) trap.
380	                    mscratch_tmask_r[branch_wid[i]] <= thread_masks[branch_wid[i]];
381	                end
382	            end
383	
384	        `ifdef VX_CFG_EXT_RTU_ENABLE
385	            // Async RTU callback trap entry: snapshot the (frozen) warp PC into
386	            // mepc as the post-mret resume point (the wait2 re-issue site), the
387	            // cause into mcause, and the full tmask into mscratch_tmask for MRET
388	            // to restore after the dispatcher ran on the narrowed lanes.
389	            if (async_trap_if.valid) begin
390	                mepc_r  [async_trap_if.wid] <= to_fullPC(warp_pcs[async_trap_if.wid]);
391	                mcause_r[async_trap_if.wid] <= async_trap_if.cause;
392	                mtval_r [async_trap_if.wid] <= '0;
393	                mscratch_tmask_r[async_trap_if.wid] <= thread_masks[async_trap_if.wid];
394	            end
395	        `endif
396	
397	            if (busy) begin
398	                cycles <= cycles + 1;
399	            end
400	        end
401	    end
