404	
405	    VX_bar_unit #(
406	        .INSTANCE_ID (`SFORMATF(("%s-barrier", INSTANCE_ID))),
407	        .CORE_ID     (CORE_ID)
408	    ) bar_unit (
409	        .clk        (clk),
410	        .reset      (reset),
411	        .req_valid  (warp_ctl_if.bar_valid),
412	        .req_wid    (warp_ctl_if.wid),
413	        .req_data   (warp_ctl_if.bar),
414	        .read_addr  (warp_ctl_if.bar_addr),
415	        .read_phase (warp_ctl_if.bar_phase),
416	        .active_warps(active_warps),
417	        .gbar_bus_if(gbar_bus_if),
418	        .unlock_valid(bar_unlock_valid),
419	        .unlock_mask(bar_unlock_mask)
420	    );
421	
422	    // split/join handling
423	
424	    VX_split_join #(
425	        .INSTANCE_ID (`SFORMATF(("%s-splitjoin", INSTANCE_ID))),
426	        .OUT_REG     (1)
427	    ) split_join (
428	        .clk        (clk),
429	        .reset      (reset),
430	        .split_valid(warp_ctl_if.split_valid),
431	        .sjoin_valid(warp_ctl_if.sjoin_valid),
432	        .wid        (warp_ctl_if.wid),
433	        .split      (warp_ctl_if.split),
434	        .sjoin      (warp_ctl_if.sjoin),
435	        .join_valid (join_valid),
436	        .join_is_dvg(join_is_dvg),
437	        .join_is_else(join_is_else),
438	        .join_wid   (join_wid),
439	        .join_tmask (join_tmask),
440	        .join_pc    (join_pc),
441	        .stack_wid  (warp_ctl_if.dvstack_wid),
442	        .stack_ptr  (warp_ctl_if.dvstack_ptr)
443	    );
