445	    // schedule the next ready warp
446	
447	    wire [`VX_CFG_NUM_WARPS-1:0] ready_warps = active_warps & ~stalled_warps;
448	
449	    // Per-warp ibuffer occupancy counter (registered full[i] keeps arbitration
450	    // off the critical path; full_n feeds an externally registered aggregate
451	    // so all_full is valid the same cycle as full[i]).
452	    localparam IBUF_CW = $clog2(`VX_CFG_IBUF_SIZE + 1);
453	
454	    wire [`VX_CFG_NUM_WARPS-1:0] schedule_onehot;
455	    logic [`VX_CFG_NUM_WARPS-1:0] ibuf_full, ibuf_full_n;
456	
457	    for (genvar i = 0; i < `VX_CFG_NUM_WARPS; ++i) begin : g_ibuf_cnt
458	        logic [IBUF_CW-1:0] size_r, size_n;
459	        wire incr = schedule_fire && schedule_onehot[i];
460	        wire decr = schedule_if.ibuf_pop[i];
461	        assign size_n = size_r + IBUF_CW'(incr) - IBUF_CW'(decr);
462	        assign ibuf_full_n[i] = (size_n == IBUF_CW'(`VX_CFG_IBUF_SIZE));
463	        always @(posedge clk) begin
464	            if (reset) begin
465	                size_r       <= '0;
466	                ibuf_full[i] <= 1'b0;
467	            end else begin
468	                size_r       <= size_n;
469	                ibuf_full[i] <= ibuf_full_n[i];
470	            end
471	        end
472	    end
473	
474	    wire [`VX_CFG_NUM_WARPS-1:0] preferred_warps = ready_warps & ~ibuf_full;
475	`ifndef L1_ENABLE
476	    // without L1, we should ensure the icache never stalls,
477	    // because it could deadlock dcache response since they share the same bus.
478	    wire [`VX_CFG_NUM_WARPS-1:0] schedule_warps = preferred_warps;
479	`else
480	    reg all_ibuf_full;
481	    always @(posedge clk) begin
482	        if (reset) all_ibuf_full <= 1'b0;
483	        else all_ibuf_full <= (& ibuf_full_n);
484	    end
485	    wire [`VX_CFG_NUM_WARPS-1:0] schedule_warps = all_ibuf_full ? ready_warps : preferred_warps;
486	`endif
487	
488	    VX_priority_encoder #(
489	        .N (`VX_CFG_NUM_WARPS)
490	    ) wid_select (
491	        .data_in   (schedule_warps),
492	        .index_out (schedule_wid),
493	        .valid_out (schedule_valid),
494	        .onehot_out(schedule_onehot)
495	    );
496	
497	    wire [`VX_CFG_NUM_WARPS-1:0][(`VX_CFG_NUM_THREADS + PC_BITS)-1:0] schedule_data;
498	    for (genvar i = 0; i < `VX_CFG_NUM_WARPS; ++i) begin : g_schedule_data
499	        assign schedule_data[i] = {thread_masks[i], warp_pcs[i]};
500	    end
501	
502	    assign {schedule_tmask, schedule_pc} = {
503	        schedule_data[schedule_wid][(`VX_CFG_NUM_THREADS + PC_BITS)-1:(`VX_CFG_NUM_THREADS + PC_BITS)-4],
504	        schedule_data[schedule_wid][(`VX_CFG_NUM_THREADS + PC_BITS)-5:0]
505	    };
506	
507	    wire [UUID_WIDTH-1:0] instr_uuid;
508	`ifdef UUID_ENABLE
509	    VX_uuid_gen #(
510	        .CORE_ID (CORE_ID)
511	    ) uuid_gen (
512	        .clk   (clk),
513	        .reset (reset),
514	        .incr  (schedule_fire),
515	        .wid   (schedule_wid),
516	        .uuid  (instr_uuid)
517	    );
518	`else
519	    assign instr_uuid = '0;
520	`endif
521	
522	    // schedule_cta_id is produced by VX_cta_dispatch from its wid->cta_id map.
523	
524	    VX_elastic_buffer #(
525	        .DATAW (`VX_CFG_NUM_THREADS + PC_BITS + NW_WIDTH + NCTA_WIDTH + UUID_WIDTH),
526	        .SIZE  (2),  // need to buffer out ready_in
527	        .OUT_REG (1) // should be registered for BRAM acces in fetch unit
528	    ) out_buf (
529	        .clk       (clk),
530	        .reset     (reset),
531	        .valid_in  (schedule_valid),
532	        .ready_in  (schedule_ready),
533	        .data_in   ({schedule_tmask, schedule_pc, schedule_wid, schedule_cta_id, instr_uuid}),
534	        .data_out  ({schedule_if.data.tmask, schedule_if.data.PC, schedule_if.data.wid, schedule_if.data.cta_id, schedule_if.data.uuid}),
535	        .valid_out (schedule_if.valid),
536	        .ready_out (schedule_if.ready)
537	    );
538	
539	    // Track committed instructions
540	
541	    reg [PERF_CTR_BITS-1:0] instret;
542	
543	    wire [`VX_CFG_NUM_WARPS-1:0] committed_warps_v = commit_sched_if.committed_warps;
544	    wire [`CLOG2(`VX_CFG_NUM_WARPS+1)-1:0] committed_warps_cnt_v;
545	    `POP_COUNT(committed_warps_cnt_v, committed_warps_v);
546	
547	    always @(posedge clk) begin
548	        if (reset) begin
549	            instret <= '0;
550	        end else begin
551	            instret <= instret + PERF_CTR_BITS'(committed_warps_cnt_v);
552	        end
553	    end
554	
555	    // Track pending instructions per warp
556	
557	    wire [`VX_CFG_NUM_WARPS-1:0] pending_warp_empty;
558	    wire [`VX_CFG_NUM_WARPS-1:0] pending_warp_alm_empty;
559	
560	    for (genvar i = 0; i < `VX_CFG_NUM_WARPS; ++i) begin : g_pending_warps
561	        localparam logic [ISSUE_ISW_W-1:0] isw = wid_to_isw(i);
562	        localparam logic [ISSUE_WIS_W-1:0] wis = wid_to_wis(i);
563	
564	        VX_pending_size #(
565	            .SIZE      (256),
566	            .ALM_EMPTY (1)
567	        ) per_warp_ctr (
568	            .clk       (clk),
569	            .reset     (reset),
570	            .incr      (issue_sched_if[isw].valid && (issue_sched_if[isw].wis == ISSUE_WIS_W'(wis))),
571	            .decr      (commit_sched_if.committed_warps[i]),
572	            .empty     (pending_warp_empty[i]),
573	            .alm_empty (pending_warp_alm_empty[i]),
574	            `UNUSED_PIN (full),
575	            `UNUSED_PIN (alm_full),
576	            `UNUSED_PIN (size)
577	        );
578	    end
579	
580	    wire busy_buf;
581	    `BUFFER_EX(busy_buf, (active_warps_n != 0 || ~(&pending_warp_empty)), 1'b1, 1, 1);
582	    assign busy = busy_buf || cta_dispatcher_busy;
583	
584	    assign warp_ctl_if.warp_pending_alm_empty = pending_warp_alm_empty;
585	
586	    // export CSRs
587	    assign sched_csr_if.cycles = cycles;
588	    assign sched_csr_if.instret = instret;
589	    assign sched_csr_if.active_warps = active_warps;
590	    assign sched_csr_if.thread_masks = thread_masks;
