593	    reg [31:0] timeout_ctr;
594	    reg timeout_enable;
595	    always @(posedge clk) begin
596	        if (reset) begin
597	            timeout_ctr    <= '0;
598	            timeout_enable <= 0;
599	        end else begin
600	            if (decode_sched_if.valid && decode_sched_if.unlock) begin
601	                timeout_enable <= 1;
602	            end
603	            if (timeout_enable && active_warps !=0 && active_warps == stalled_warps) begin
604	                timeout_ctr <= timeout_ctr + 1;
605	            end else if (active_warps == 0 || active_warps != stalled_warps) begin
606	                timeout_ctr <= '0;
607	            end
608	        end
609	    end
610	
611	`ifdef EXT_SCHED_STALL_TIMEOUT
612	    localparam SCHED_STALL_TIMEOUT = `EXT_SCHED_STALL_TIMEOUT;
613	`else
614	    localparam SCHED_STALL_TIMEOUT = STALL_TIMEOUT;
615	`endif
616	`ifdef EXT_SCHED_TIMEOUT_DUMP
617	    always @(posedge clk) begin
618	        if (!reset && (timeout_ctr == (SCHED_STALL_TIMEOUT - 1))) begin
619	            $display("*** %s scheduler-timeout dump: active=%b stalled=%b", INSTANCE_ID, active_warps, stalled_warps);
620	            for (integer wi = 0; wi < `VX_CFG_NUM_WARPS; ++wi) begin
621	                $display("    wid=%0d stalled=%0d pc=0x%0h tmask=%b",
622	                         wi, stalled_warps[wi], to_fullPC(warp_pcs[wi]), thread_masks[wi]);
623	            end
624	        end
625	    end
626	`endif
627	    `RUNTIME_ASSERT(timeout_ctr < SCHED_STALL_TIMEOUT, ("*** %s timeout: active_warps=%b, stalled_warps=%b", INSTANCE_ID, active_warps, stalled_warps))
628	
629	`ifdef PERF_ENABLE
630	    reg [PERF_CTR_BITS-1:0] perf_sched_idles;
631	    reg [PERF_CTR_BITS-1:0] perf_active_warps;
632	    reg [PERF_CTR_BITS-1:0] perf_stalled_warps;
633	    reg [PERF_CTR_BITS-1:0] perf_issued_warps;
634	    reg [PERF_CTR_BITS-1:0] perf_issued_threads;
635	    reg [PERF_CTR_BITS-1:0] perf_branches;
636	    reg [PERF_CTR_BITS-1:0] perf_divergence;
637	
638	    wire [`CLOG2(`VX_CFG_NUM_WARPS+1)-1:0] stalled_warps_cnt;
639	    wire [`CLOG2(`VX_CFG_NUM_ALU_BLOCKS+1)-1:0] branches_cnt;
640	    wire [`CLOG2(`VX_CFG_NUM_THREADS+1)-1:0] issued_threads_cnt;
641	
642	    wire schedule_idle = ~schedule_valid;
643	    wire has_divergence = warp_ctl_if.split_valid && warp_ctl_if.split.is_dvg;
644	    wire [`VX_CFG_NUM_THREADS-1:0] issued_threads = {`VX_CFG_NUM_THREADS{schedule_if_fire}} & schedule_if.data.tmask;
645	
646	    `POP_COUNT(stalled_warps_cnt, stalled_warps);
647	    `POP_COUNT(issued_threads_cnt, issued_threads);
648	    `POP_COUNT(branches_cnt, branch_valid);
649	
650	    always @(posedge clk) begin
651	        if (reset) begin
652	            perf_sched_idles   <= '0;
653	            perf_active_warps  <= '0;
654	            perf_stalled_warps <= '0;
655	            perf_issued_warps  <= '0;
656	            perf_issued_threads<= '0;
657	            perf_branches      <= '0;
658	            perf_divergence    <= '0;
659	        end else begin
660	            perf_sched_idles   <= perf_sched_idles + PERF_CTR_BITS'(schedule_idle);
661	            perf_active_warps  <= perf_active_warps + PERF_CTR_BITS'(active_warps_cnt);
662	            perf_stalled_warps <= perf_stalled_warps + PERF_CTR_BITS'(stalled_warps_cnt);
663	            perf_issued_warps  <= perf_issued_warps + PERF_CTR_BITS'(schedule_if_fire);
664	            perf_issued_threads<= perf_issued_threads + PERF_CTR_BITS'(issued_threads_cnt);
665	            perf_branches      <= perf_branches + PERF_CTR_BITS'(branches_cnt);
666	            perf_divergence    <= perf_divergence + PERF_CTR_BITS'(has_divergence);
667	        end
668	    end
669	
670	    assign sched_perf.idles         = perf_sched_idles;
671	    assign sched_perf.active_warps  = perf_active_warps;
672	    assign sched_perf.stalled_warps = perf_stalled_warps;
673	    assign sched_perf.issued_warps  = perf_issued_warps;
674	    assign sched_perf.issued_threads= perf_issued_threads;
675	    assign sched_perf.branches      = perf_branches;
676	    assign sched_perf.divergence    = perf_divergence;
677	`endif
678	
679	`ifdef DBG_TRACE_PIPELINE
680	    for (genvar w = 0; w < `VX_CFG_NUM_WARPS; ++w) begin : g_trace_warp_status
681	        always @(posedge clk) begin
682	            if (active_warps_n[w] != active_warps[w]
683	             || (active_warps[w] && (stalled_warps_n[w] != stalled_warps[w]
684	                                  || thread_masks_n[w] != thread_masks[w]))) begin
685	                `TRACE(1, ("%t: %s warp-state: wid=%0d, active=%b, stalled=%b, tmask=%b\n",
686	                    $time, INSTANCE_ID, w, active_warps_n[w], stalled_warps_n[w], thread_masks_n[w]
687	                ))
688	            end
689	        end
690	    end
691	
692	    always @(posedge clk) begin
693	        if (schedule_fire) begin
694	            `TRACE(1, ("%t: %s dispatch: wid=%0d, cta_id=%0d, PC=0x%0h, tmask=%b (#%0d)\n", $time, INSTANCE_ID, schedule_wid, schedule_cta_id, to_fullPC(schedule_pc), schedule_tmask, instr_uuid))
695	        end
696	    end
697	`endif
698	
699	endmodule
700

