8	// Unless required by applicable law or agreed to in writing, software
9	// distributed under the License is distributed on an "AS IS" BASIS,
10	// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
11	// See the License for the specific language governing permissions and
12	// limitations under the License.
13	
14	`include "VX_define.vh"
15	
16	module VX_wctl_unit import VX_gpu_pkg::*; #(
17	    parameter `STRING INSTANCE_ID = "",
18	    parameter NUM_LANES = 1
19	) (
20	    input wire              clk,
21	    input wire              reset,
22	
23	    // Inputs
24	    VX_execute_if.slave     execute_if,
25	    VX_txbar_bus_if.slave   txbar_bus_if,
26	
27	    // Outputs
28	    VX_warp_ctl_if.master   warp_ctl_if,
29	    VX_result_if.master     result_if
30	);
31	    `UNUSED_SPARAM (INSTANCE_ID)
32	    localparam LANE_BITS  = `CLOG2(NUM_LANES);
33	    localparam PID_BITS   = `CLOG2(`VX_CFG_NUM_THREADS / NUM_LANES);
34	    localparam WCTL_WIDTH = $bits(tmc_t) + $bits(wspawn_t) + $bits(split_t) + $bits(join_t) + $bits(barrier_t);
35	
36	    `UNUSED_VAR (execute_if.data.rs3_data)
37	
38	    tmc_t       tmc;
39	    wspawn_t    wspawn;
40	    split_t     split;
41	    join_t      sjoin;
42	    barrier_t   bar;
43	
44	    wire is_wspawn = (execute_if.data.op_type == INST_SFU_WSPAWN);
45	    wire is_tmc    = (execute_if.data.op_type == INST_SFU_TMC);
46	    wire is_pred   = (execute_if.data.op_type == INST_SFU_PRED);
47	    wire is_split  = (execute_if.data.op_type == INST_SFU_SPLIT);
48	    wire is_join   = (execute_if.data.op_type == INST_SFU_JOIN);
49	    wire is_bar    = (execute_if.data.op_type == INST_SFU_BAR);
50	    wire is_wsync  = (execute_if.data.op_type == INST_SFU_WSYNC);
51	
52	    wire wctl_valid;
53	    wire wspawn_valid, tmc_valid, split_valid, sjoin_valid, bar_valid, wsync_valid;
54	
55	    wire [`UP(LANE_BITS)-1:0] last_tid;
56		    if (LANE_BITS != 0) begin : g_last_tid
57		        VX_priority_encoder #(
58		            .N (NUM_LANES),
59		            .REVERSE (1)
60		        ) last_tid_select (
61		            .data_in (execute_if.data.header.tmask),
62		            .index_out (last_tid),
63		            `UNUSED_PIN (onehot_out),
64	            `UNUSED_PIN (valid_out)
65	        );
66	    end else begin : g_no_tid
67	        assign last_tid = 0;
68	    end
69	
70	    wire [`VX_CFG_XLEN-1:0] rs1_data = execute_if.data.rs1_data[last_tid];
71	    wire [`VX_CFG_XLEN-1:0] rs2_data = execute_if.data.rs2_data[last_tid];
72	    `UNUSED_VAR (rs1_data)
73	
74	    wire not_pred = execute_if.data.op_args.wctl.is_cond_neg;
75	
76	    wire [NUM_LANES-1:0] taken;
77	    for (genvar i = 0; i < NUM_LANES; ++i) begin : g_taken
78	        assign taken[i] = (execute_if.data.rs1_data[i][0] ^ not_pred);
79	    end
80	
81	    logic [`VX_CFG_NUM_THREADS-1:0] then_tmask;
82	    logic [`VX_CFG_NUM_THREADS-1:0] else_tmask;
83	
84	    if (PID_BITS != 0) begin : g_pid
85	        reg [`VX_CFG_NUM_WARPS-1:0][2*`VX_CFG_NUM_THREADS-1:0] tmask_table;
86	
87	        wire [2*`VX_CFG_NUM_THREADS-1:0] tmask_r = tmask_table[execute_if.data.header.wid];
88	
89	        always @(*) begin
90	            {else_tmask, then_tmask} = execute_if.data.header.sop ? '0 : tmask_r;
91	            then_tmask[execute_if.data.header.pid * NUM_LANES +: NUM_LANES] = taken & execute_if.data.header.tmask;
92	            else_tmask[execute_if.data.header.pid * NUM_LANES +: NUM_LANES] = ~taken & execute_if.data.header.tmask;
93	        end
94	
95	        always @(posedge clk) begin
96	            if (execute_if.valid) begin
97	                tmask_table[execute_if.data.header.wid] <= {else_tmask, then_tmask};
98	            end
99	        end
100	    end else begin : g_no_pid
101	        assign then_tmask = taken & execute_if.data.header.tmask;
102	        assign else_tmask = ~taken & execute_if.data.header.tmask;
103	    end
104	
105	    wire has_then = (then_tmask != 0);
106	    wire has_else = (else_tmask != 0);
107	
108	    // tmc / pred
109	
110	    wire [`VX_CFG_NUM_THREADS-1:0] pred_mask = has_then ? then_tmask : rs2_data[`VX_CFG_NUM_THREADS-1:0];
111	    assign tmc_valid = wctl_valid && (is_tmc || is_pred);
112	    assign tmc.tmask = is_pred ? pred_mask : rs1_data[`VX_CFG_NUM_THREADS-1:0];
113	
114	    // split
115	
116	    wire [`CLOG2(`VX_CFG_NUM_THREADS+1)-1:0] then_tmask_cnt, else_tmask_cnt;
117	    `POP_COUNT(then_tmask_cnt, then_tmask);
118	    `POP_COUNT(else_tmask_cnt, else_tmask);
119	    wire then_first = (then_tmask_cnt <= else_tmask_cnt);
120	    wire [`VX_CFG_NUM_THREADS-1:0] taken_tmask = then_first ? then_tmask : else_tmask;
121	    wire [`VX_CFG_NUM_THREADS-1:0] ntaken_tmask = then_first ? else_tmask : then_tmask;
122	
123	    assign split_valid      = wctl_valid && is_split;
124	    assign split.is_dvg     = has_then && has_else;
125	    assign split.then_tmask = taken_tmask;
126	    assign split.else_tmask = ntaken_tmask;
127	    assign split.next_pc    = execute_if.data.header.PC + from_fullPC(`VX_CFG_XLEN'(4));
128	
129	    // join
130	
131	    assign sjoin_valid      = wctl_valid && is_join;
132	    assign sjoin.tmask      = then_tmask | else_tmask;
133	    assign sjoin.stack_ptr  = rs1_data[DV_STACK_SIZEW-1:0];
134	
135	    // barrier
136	
137	    wire [BAR_ADDR_W-1:0] wctl_bar_addr;
138	    `CONCAT(wctl_bar_addr, rs1_data[NW_BITS-1:0], rs1_data[BAR_ID_SHIFT +: NB_BITS], NW_BITS, NB_BITS)
139	
140	    wire wctl_bar_enable = wctl_valid && is_bar;
141	
142	    // expect_tx variant of barrier_arrive: rs2[31]=1 flags pre-registration
143	    // of pending transaction events. Routed through the existing event path
144	    // (is_event + phase=1) so VX_bar_unit's increment branch handles it.
145	    wire is_tx_expect   = wctl_bar_enable
146	                       && execute_if.data.op_args.wctl.is_bar_arrive
147	                       && rs2_data[31];
148	
149	    assign bar_valid    = wctl_bar_enable || txbar_bus_if.valid;
150	    assign bar.id       = rs1_data[BAR_ID_SHIFT +: NB_BITS];
151	    assign bar.is_event = (txbar_bus_if.valid && ~wctl_bar_enable) || is_tx_expect;
152	    assign bar.is_sync  = execute_if.data.op_args.wctl.is_sync_bar;
153	    assign bar.is_global= wctl_bar_enable && rs1_data[31];
154	    // expect_tx is not a normal arrival (it does not advance arrive_count)
155	    assign bar.is_arrive= (execute_if.data.op_args.wctl.is_bar_arrive && ~rs2_data[31]) || execute_if.data.op_args.wctl.is_sync_bar;
156	    // expect_tx → phase=1 (attach/increment); legacy txbar release → phase=0
157	    assign bar.phase    = is_tx_expect ? 1'b1 : (wctl_bar_enable ? rs2_data[0] : ~txbar_bus_if.data.is_done);
158	    // For expect_tx: size_m1 carries (count - 1); for normal arrive: (num_warps - 1).
159	    // bar_unit will + 1 when consuming on the event path so the actual increment is `count`.
160	    assign bar.size_m1  = rs2_data[BAR_SIZE_W-1:0] - BAR_SIZE_W'(1);
161	
162	    assign txbar_bus_if.ready = ~wctl_bar_enable;
163	
164	    // wspawn
165	
166	    wire [`VX_CFG_NUM_WARPS-1:0] wspawn_wmask;
167	    for (genvar i = 0; i < `VX_CFG_NUM_WARPS; ++i) begin : g_wspawn_wmask
168	        assign wspawn_wmask[i] = (i < rs1_data[NW_BITS:0]) && (i != execute_if.data.header.wid);
169	    end
170	    assign wspawn_valid = wctl_valid && is_wspawn;
171	    assign wspawn.wmask = wspawn_wmask;
172	    assign wspawn.pc    = from_fullPC(rs2_data);
173	
174	    // Scheduler response setup
175	
176	    assign warp_ctl_if.dvstack_wid = execute_if.data.header.wid;
177	    assign warp_ctl_if.bar_addr = wctl_bar_enable ? wctl_bar_addr : txbar_bus_if.data.addr;
178	
179	    // Send scheduler request
180	
181	    // WSYNC: hold execute until this warp's pipeline is drained (alm_empty=1
182	    // means only WSYNC itself is pending — all prior instructions committed).
183	    wire wsync_drain = execute_if.valid && is_wsync
184	                    && !warp_ctl_if.warp_pending_alm_empty[execute_if.data.header.wid];
185	
186	    // BAR (vx_barrier or vx_barrier_arrive) drains LSU before continuing.
187	    wire bar_drain = execute_if.valid && is_bar && !warp_ctl_if.lsu_sched_drained;
188	
189	    wire execute_fire = execute_if.valid && execute_if.ready;
190	    assign wctl_valid = execute_fire && execute_if.data.header.eop;
191	
192	    assign wsync_valid = wctl_valid && is_wsync;
193	
194	    VX_pipe_register #(
195	        .DATAW (6 + NW_WIDTH + WCTL_WIDTH),
196	        .RESETW (1)
197	    ) wctl_reg (
198	        .clk      (clk),
199	        .reset    (reset),
200	        .enable   (1'b1),
201	        .data_in  ({
202	            tmc_valid,
203	            wspawn_valid,
204	            split_valid,
205	            sjoin_valid,
206	            bar_valid,
207	            wsync_valid,
208	            execute_if.data.header.wid,
209	            tmc,
210	            wspawn,
211	            split,
212	            sjoin,
213	            bar
214	        }),
215	        .data_out ({
216	            warp_ctl_if.tmc_valid,
217	            warp_ctl_if.wspawn_valid,
218	            warp_ctl_if.split_valid,
219	            warp_ctl_if.sjoin_valid,
220	            warp_ctl_if.bar_valid,
221	            warp_ctl_if.wsync_valid,
222	            warp_ctl_if.wid,
223	            warp_ctl_if.tmc,
224	            warp_ctl_if.wspawn,
225	            warp_ctl_if.split,
226	            warp_ctl_if.sjoin,
227	            warp_ctl_if.bar
228	        })
229	    );
230	
231	    // Send result
232	
233	    wire [DV_STACK_SIZEW-1:0] dvstack_ptr_r;
234	    wire bar_rsp_valid = is_bar && execute_if.data.op_args.wctl.is_bar_arrive;
235	    wire bar_rsp_valid_r;
236	    wire bar_phase_r;
237	
238	    wire rsp_buf_ready;
239	    VX_elastic_buffer #(
240	        .DATAW ($bits(sfu_header_t) + DV_STACK_SIZEW + 1 + 1),
241	        .SIZE  (2)
242	    ) rsp_buf (
243	        .clk       (clk),
244	        .reset     (reset),
245	        .valid_in  (execute_if.valid && !wsync_drain && !bar_drain),
246	        .ready_in  (rsp_buf_ready),
247	        .data_in   ({execute_if.data.header, warp_ctl_if.dvstack_ptr, warp_ctl_if.bar_phase, bar_rsp_valid}),
248	        .data_out  ({result_if.data.header,  dvstack_ptr_r,           bar_phase_r,           bar_rsp_valid_r}),
249	        .valid_out (result_if.valid),
250	        .ready_out (result_if.ready)
251	    );
252	    assign execute_if.ready = rsp_buf_ready && !wsync_drain && !bar_drain;
253	
254	    // Result data
255	    for (genvar i = 0; i < NUM_LANES; ++i) begin : g_result_if
256	        assign result_if.data.data[i] = bar_rsp_valid_r ? `VX_CFG_XLEN'(bar_phase_r) : `VX_CFG_XLEN'(dvstack_ptr_r);
257	    end
258	
259	endmodule
260

